	inline constexpr std::array<CurseCity, 10> kCurseCities{ {
		CurseCity{ "the Sleeping Giant Inn", 0x013163, 0x98C, CursePlace{ "Alvor's forge", 21406.0f, -44778.0f, -82.0f }, "Where the hammer wakes the anvil every morning and the river hears it ring, the valley's dead are gathering. Go to the smith's fire.", { CursePlace{ "the Sleeping Giant Inn", 23260.0f, -44476.0f, -8.0f }, CursePlace{ "the Riverwood Trader", 21954.0f, -45644.0f, 105.0f }, CursePlace{ "the mill", 23509.0f, -47197.0f, -5.0f } } },
		CurseCity{ "the Gildergreen", 0x018A56, 0x98D, CursePlace{ "the Hall of the Dead", 22752.0f, -2016.0f, -3008.0f }, "Below the Jarl's hall, where Arkay's priest lays the city's dead in beds of stone, the beds are empty. Go where Whiterun buries its own.", { CursePlace{ "Jorrvaskr", 27392.0f, -4202.0f, -2569.0f }, CursePlace{ "the Temple of Kynareth", 23241.0f, -3404.0f, -2966.0f }, CursePlace{ "the Bannered Mare", 25670.0f, -7633.0f, -3237.0f } } },
		CurseCity{ "the Blue Palace", 0x018A5A, 0x98E, CursePlace{ "the Bards College", -54480.0f, 104736.0f, -8608.0f }, "Where Solitude teaches its young to sing of the dead, the dead have come to listen. Go where the songs are learned.", { CursePlace{ "Castle Dour", -62806.0f, 108069.0f, -7200.0f }, CursePlace{ "the Temple of the Divines", -58718.0f, 110639.0f, -7936.0f }, CursePlace{ "the Blue Palace", -50608.0f, 99960.0f, -8608.0f } } },
		CurseCity{ "the Palace of the Kings", 0x018A57, 0x98F, CursePlace{ "Candlehearth Hall", 134591.0f, 37193.0f, -12111.0f }, "There is a candle in this city that has burned since its first stone was laid, and never once gone out. The dead are drawn to it like moths. Find the hearth that never goes cold.", { CursePlace{ "the Palace of the Kings", 134716.0f, 42717.0f, -11867.0f }, CursePlace{ "the Hall of the Dead", 131492.0f, 38362.0f, -12608.0f }, CursePlace{ "the Grey Quarter", 140312.0f, 39816.0f, -13101.0f } } },
		CurseCity{ "the Hall of the Dead", 0x018A59, 0x990, CursePlace{ "the Temple of Dibella", -176860.0f, 4485.0f, -1741.0f }, "High in the city of stone, where Markarth kneels to beauty, beauty has turned grey and cold. Climb to the goddess's door.", { CursePlace{ "Understone Keep", -179040.0f, 3308.0f, -2176.0f }, CursePlace{ "the Hall of the Dead", -177740.0f, 1528.0f, -2296.0f }, CursePlace{ "the Silver-Blood Inn", -174538.0f, 4971.0f, -3306.0f } } },
		CurseCity{ "the Temple of Mara", 0x018A58, 0x991, CursePlace{ "the Ratway's gate", 172802.0f, -97209.0f, 10693.0f }, "Below the boardwalk, by the green water where thieves come and go unseen, the drowned are climbing out. Go down to the canal's iron door.", { CursePlace{ "Mistveil Keep", 173396.0f, -100216.0f, 11496.0f }, CursePlace{ "the Temple of Mara", 176323.0f, -97022.0f, 11392.0f }, CursePlace{ "the Bee and Barb", 172928.0f, -96100.0f, 11140.0f } } },
		CurseCity{ "the old graveyard", 0x018A49, 0x992, CursePlace{ "the graveyard", -34558.0f, -84351.0f, -3448.0f }, "More dead than living lie in this town's earth, and tonight they are restless in their rows. Go where Falkreath counts its dead.", { CursePlace{ "the Jarl's Longhouse", -29466.0f, -87603.0f, -2960.0f }, CursePlace{ "Dead Man's Drink", -32175.0f, -87653.0f, -3099.0f }, CursePlace{ "Dengeir's Hall", -30503.0f, -85227.0f, -3108.0f } } },
		CurseCity{ "the edge of the marsh", 0x018A53, 0x993, CursePlace{ "the Thaumaturgist's Hut", -37996.0f, 64969.0f, -13681.0f }, "In a crooked hut at the marsh's edge, roots and mushrooms steep in the dark, and the drowned of the swamp come to drink. Find the brewer's door.", { CursePlace{ "Highmoon Hall", -38660.0f, 63424.0f, -13786.0f }, CursePlace{ "the Moorside Inn", -40054.0f, 65484.0f, -13802.0f }, CursePlace{ "Falion's House", -35451.0f, 65876.0f, -13913.0f } } },
		CurseCity{ "the frozen harbour", 0x018A50, 0x994, CursePlace{ "the Quicksilver Mine", 27359.0f, 105202.0f, -13795.0f }, "Where men cut a metal that runs like water out of the cold hill, the dead have dug their way up. Go to the mouth of the mine.", { CursePlace{ "the White Hall", 32883.0f, 102685.0f, -13187.0f }, CursePlace{ "the Windpeak Inn", 29359.0f, 102088.0f, -13209.0f }, CursePlace{ "Rustleif's forge", 29742.0f, 104129.0f, -13771.0f } } },
		CurseCity{ "the bridge to the College", 0x018A51, 0x995, CursePlace{ "the Frozen Hearth", 110268.0f, 101613.0f, -8955.0f }, "The rest of this town turns mages from its door. One fire still burns for them, and tonight the dead have found it. Go to the hearth that welcomes the College.", { CursePlace{ "the Jarl's Longhouse", 109763.0f, 101024.0f, -8950.0f }, CursePlace{ "Ranmir's house", 108591.0f, 103006.0f, -8783.0f }, CursePlace{ "the north road houses", 108755.0f, 104026.0f, -8997.0f } } },
	} };
	inline constexpr std::array<std::uint32_t, 10> kRiteQuests{ 0xBEF, 0xBF0, 0xBF1, 0xBF2, 0xBF3, 0xBF4, 0xBF5, 0xBF6, 0xBF7, 0xBF8 };   // the cities' quests in the journal
	struct TrialDef { std::string_view id, title, shortText, goal, text; std::array<int, 6> n, seconds; };  // per Skyrim difficulty, Novice..Legendary
	inline constexpr std::array<TrialDef, 4> kTrials{ {
		TrialDef{ "restless", "Lay the Restless to Rest", "Slay the risen in the altar's light", "Slay the risen in the light of the Echo Altar of {city}", "Alduin's mist bars the road to Sovngarde, and the dead of {city} have nowhere to go. Put them down within the light of the city's Echo Altar and their souls rise through the mist at last. Lay {n} of the risen to rest in the altar's light.", { 15, 19, 23, 27, 31, 35 }, { 0, 0, 0, 0, 0, 0 } },
		TrialDef{ "whisper", "The Stone's Whisper", "Find the place the altar's voice names", "Find the place the altar's voice names in {city}, and slay the risen there", "At night a voice speaks from the Echo Altar of {city}, and it speaks in riddles. Find the place it names, and hold it against the dead: slay {n} of the risen there.", { 10, 12, 14, 16, 18, 20 }, { 0, 0, 0, 0, 0, 0 } },
		TrialDef{ "echo", "Repeat the Echo", "Touch the stones in the order the altar sings them", "At midnight, touch the altar's six stones in the order it sings them", "The Tongues woke their altars by answering them: the stone sang, and they sang it back. At midnight six stones rise round the Echo Altar of {city} and it flashes its runes on them, one by one. Touch the stones in the same order while the dead come for you. Miss a note and it sings again at the next hour.", { 4, 4, 5, 5, 6, 6 }, { 0, 0, 0, 0, 0, 0 } },
		TrialDef{ "seals", "Break the Priest's Seals", "Shatter the Dragon Priest's three seals", "Break the Dragon Priest's three seals in {city}", "The Dragon Priest who holds the altar of {city} silent has bound it with three seals of dragon script, set at the city's great places and each kept by one of his chosen. Kill each guard and strike its seal. When the last one breaks, the priest comes out to meet you.", { 3, 3, 3, 3, 3, 3 }, { 0, 0, 0, 0, 0, 0 } },
	} };
	enum TrialId : int { kTrial_restless = 0, kTrial_whisper = 1, kTrial_echo = 2, kTrial_seals = 3 };
	struct CityBoss { std::string_view name, row, text; float health; std::uint32_t weapon; std::string_view weaponName; };  // each city's Dragon Priest, the fourth step (health: in a zombie's night health); weapon: his drop (local id)
	inline constexpr std::array<CityBoss, 10> kCityBosses{ {
		CityBoss{ "Vahlok the Jailor", "priest_draugr", "Vahlok kept the cult's prisoners in the Merethic Era, and his oath to Alduin was the last he swore. It has brought him out of his tomb and across the sea to the barrow above Riverwood, to keep the valley's altar dark.", 20.0f, 0xE87, "Jailor's Keyhammer" },
		CityBoss{ "Nahkriin, Warden of Skuldafn", "priest_draman", "Nahkriin guarded Skuldafn, the gate to Sovngarde, for Alduin, and the mist that bars Sovngarde's door is his to keep. He has come down from the mountains to the plains, so that Whiterun's dead never find the way home.", 26.0f, 0xE88, "Mistblade" },
		CityBoss{ "Volsung of Volskygge", "priest_draugr2", "Volsung ruled the peaks above Haafingar from Volskygge, and his mask let him breathe where no man could. He climbs down to Solitude now, and the dead of the Blue Palace's crypts rise at his word.", 26.0f, 0xE89, "Windcutter" },
		CityBoss{ "Zahkriisos the Frost-Priest", "priest_draman2", "Zahkriisos lay in his tomb on Solstheim until Alduin's shout crossed the Sea of Ghosts. He walked over the ice to Windhelm's docks, and the cold he carries stops a heart.", 28.0f, 0xE8A, "Glacier Greatsword" },
		CityBoss{ "Otar the Mad", "priest_ancient", "Otar was so cruel that his own cult sealed him alive in Ragnvald. His oath to Alduin outlived his reason. He climbs out of the Reach's stone beneath Markarth to guard its altar.", 24.0f, 0xE8B, "Storm Blade" },
		CityBoss{ "Rahgot of Forelhost", "priest_draman_anc", "Rahgot's followers poisoned themselves in Forelhost rather than surrender him to the Tongues. They rise with him now, and the Rift's dead follow them down to Riften's altar.", 22.0f, 0xE8C, "Sacrifice Knife" },
		CityBoss{ "Krosis of Shearpoint", "priest_ancient2", "Krosis guarded the word at Shearpoint, mourning, for a thousand years. Alduin's shout gave him something to do with his sorrow: he comes down to Falkreath's graveyard to keep its children in the ground no longer.", 26.0f, 0xE8D, "Grief Blade" },
		CityBoss{ "Hevnoraak of Valthume", "priest_draman_anc2", "Hevnoraak's servants sealed him in Valthume to stop him rising. The seal could not hold against SLEN TIID VO: he walks out of the marsh fog, and Hjaalmarch's drowned dead follow him.", 24.0f, 0xE8E, "Sealbreaker" },
		CityBoss{ "Vokun of High Gate", "priest_mythic", "Vokun was a priest of shadows, and the Nightcaller's dreamers in Dawnstar dreamed his return a thousand years before it came. Kill him, and Dawnstar's nightmares end.", 22.0f, 0xE8F, "Nightcaller's Scythe" },
		CityBoss{ "Morokei of Labyrinthian", "priest_draman_myth", "Morokei once held the Staff of Magnus in Labyrinthian, and the College has feared him ever since. He has come to the cliffs above Winterhold, and the storm he calls has not finished yet.", 24.0f, 0xE90, "Arcane Maul" },
	} };
	inline constexpr std::uint32_t kCurseIntroGlobal = 0x996, kStandLayoutGlobal = 0x9DB, kDirgeBook = 0x9DC, kGuideBook = 0xC0A;
	inline constexpr std::string_view kCursePrologueTitle = "THE CURSE OF ALDUIN", kCursePrologue = "Helgen burned, and you lived. Alduin did not stay to finish what he started: he flew north over the smoke, and as he went he shouted three words into the earth - SLEN TIID VO, Flesh, Time, Undo. It is the shout he uses to raise his dragons from their burial mounds, but this time it fell on every grave in Skyrim, and every barrow answered. His shout hangs like a mist over every road the dead walk - to Shor's hall and every other - and now the dead of Skyrim cannot pass: the mist turns them back, and when the sun goes down Alduin's voice throws them down to Skyrim again in beams of red light. The Dragon Priests who swore themselves to Alduin in the Merethic Era remember their oaths and wake with them. Only the Echo Altars the ancient Tongues raised in every hold can still his voice, and they have gone dark. Wake them, city by city, and their dead will sleep again.", kCurseLiftedBanner = "THE ECHO ALTAR OF {CITY} AWAKENS", kCurseLiftedText = "The altar of {city} rings with the old Tongues' answer, and Alduin's voice falls silent here. Its dead sleep again - none of the curse's dead will rise within its bounds.", kCurseFreedAll = "Every Echo Altar in Skyrim is awake. Alduin's voice lingers only in the wild places now - and in the echo he left on the Throat of the World.";
