	inline constexpr std::array<EggDef, 4> kEggs{ {
		EggDef{ "wyrm", "The Ghost Pride", "The Greybeards call you to High Hrothgar: the Soulcaller's Staff waits in the great hall.", 0, { EggStep{ 0, 3, 0, true, 2500.0f, 14000.0f, false, 0.0f, "spirit cat", "Calm the three spirit sabre cats roaming within 200 m of the altar at night - sneak up on each", -1, false, "Three spirit cats stalk the edges of this city by moonlight. They fear the hunter. Come to them quietly.", "Three souls pad behind you now.", "flee", "The Shy Pride" }, EggStep{ 6, 30, 0, true, 0.0f, 0.0f, false, 0.0f, "", "The hunt: 30 of the dead slain by your summons at night, a spirit cat at your side", -1, false, "A pride must hunt. Let your servants kill thirty of the dead tonight, and keep the spirit at your side alive.", "The pride has tasted the hunt.", "escort", "The Hunt" }, EggStep{ 1, 4, 0, true, 350.0f, 800.0f, false, 0.0f, "roaring stone", "Touch the four roaring stones in the order you heard them", -1, false, "Four stones remember the pride's roar. Listen to the order they call, then answer them.", "The roar is whole again.", "sound", "The Roaring Stones" }, EggStep{ 4, 18, 0, true, 0.0f, 0.0f, false, 0.0f, "", "Hold the altar against the dead without striking a blow yourself - only your summons may kill", -1, false, "Stand at this altar while the dead come. Lift no blade. Let only what you call do the killing.", "The den is ready.", "summonsonly", "The Den" }, EggStep{ 5, 1, 0, true, 0.0f, 0.0f, false, 0.0f, "The Bone-Caller", "Break the Bone-Caller's three soul-chains, then kill him", 73, false, "The Bone-Caller chains the Old King's soul. Break the chains, then break him.", "The Old King runs free.", "chains", "The Bone-Caller" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" } }, 5, 0xCE1, 0xCE5, "pride", "Listen... the ghost-cats that guarded the Tongues still prowl. Gather their scattered souls, and the Soulcaller's Staff will answer you.", "The pride is whole. The Greybeards are calling. The Soulcaller's Staff waits at High Hrothgar." },
		EggDef{ "sixfires", "The Eye of Magnus", "The Greybeards call you to High Hrothgar: the Wyrmspine Javelin waits in the great hall.", 1, { EggStep{ 0, 3, 0, true, 500.0f, 1100.0f, false, 20.0f, "seal", "Open the ember, rime and storm seals, each with a spell of its element, within 20 seconds of the first", -1, false, "Three seals sleep near this altar: ember, rime and storm. Strike each with its own element, before the first goes dark again.", "The seals are open.", "seals", "The Three Seals" }, EggStep{ 0, 5, 0, true, 600.0f, 1500.0f, false, 60.0f, "falling star", "Catch five falling pieces of the Eye at night within 60 seconds", -1, false, "Pieces of the Eye are falling tonight. Catch five before they burn out.", "The light is gathered.", "", "Falling Stars" }, EggStep{ 1, 4, 0, true, 350.0f, 800.0f, false, 0.0f, "light-stone", "Strike the four light-stones in order: fire, frost, storm, then sun", -1, false, "Four stones, four colours. Ember before frost, frost before storm, and storm before the sun. Strike them so.", "The prism shines.", "prism", "The Prism" }, EggStep{ 6, 40, 0, true, 0.0f, 0.0f, false, 0.0f, "", "40 of the dead slain with Destruction at night - at least 10 each by fire, frost and storm", -1, false, "Burn forty of the dead tonight. Fire, frost and storm... the Eye hungers for all three.", "The Eye is kindled.", "elemsplit", "Fire, Frost and Storm" }, EggStep{ 5, 1, 0, true, 0.0f, 0.0f, false, 0.0f, "The Great Anomaly", "Unmake the Great Anomaly - strike it only with an element it isn't wearing", 123, false, "The Great Anomaly wears every element in turn. Strike it with what it fears, never with what it wears.", "The Anomaly is unmade.", "anomaly", "The Great Anomaly" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" } }, 5, 0xCE2, 0xCE6, "eye", "A god's eye fell to Nirn, and the curse buried its light. Wake its fire, frost and storm, and the Wyrmspine Javelin is yours to claim.", "The Eye sees again. The Greybeards are calling. The Wyrmspine Javelin waits at High Hrothgar." },
		EggDef{ "vortex", "The Elixir of Aetherius", "The Greybeards call you to High Hrothgar: the Mutagen Staff waits in the great hall.", 2, { EggStep{ 0, 6, 0, true, 700.0f, 1500.0f, false, 0.0f, "essence", "Kill the six element-wrapped dead at night, each with a flask of its own element, and take their essences", -1, false, "Six of the dead rise tonight, each wrapped in an element. Answer each with its own flask, and take what falls.", "Six essences. Carry them carefully.", "wrapped", "The Wrapped Dead" }, EggStep{ 2, 1, 0, false, 0.0f, 0.0f, false, 0.0f, "the altar", "Carry the essences to the altar before dawn", -1, false, "A crucible needs an altar's fire. Bring the essences here before dawn.", "The crucible is lit.", "dawn", "Before Dawn" }, EggStep{ 1, 4, 0, true, 350.0f, 800.0f, false, 0.0f, "brazier", "Light the four braziers with your flasks in the order they flicker", -1, false, "Four braziers flicker a formula. Copy it with your flasks, in the order they burn.", "The formula holds.", "flaskorder", "The Formula" }, EggStep{ 4, 16, 0, true, 0.0f, 0.0f, true, 0.0f, "", "Hold the altar against the dead without being hurt", -1, false, "The brew must not be shaken. Hold this altar against the dead, and do not bleed.", "The Elixir is settling.", "", "The Steady Hand" }, EggStep{ 5, 1, 0, true, 0.0f, 0.0f, false, 0.0f, "The Matriarch", "Bring down the Matriarch - never the same element twice in a row", 67, false, "The Matriarch drinks whatever strikes her. Never feed her the same element twice.", "The Matriarch is spent.", "matriarch", "The Matriarch" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" } }, 5, 0xCE3, 0xCE7, "stone", "Every element can be bottled... even the curse. Brew the Elixir of Aetherius, and the Mutagen Staff will be yours.", "The Elixir is brewed. The Greybeards are calling. The Mutagen Staff waits at High Hrothgar." },
		EggDef{ "slayer", "The Slayer's Oath", "The Greybeards call you to High Hrothgar: the Dragon Slayer waits in the great hall.", 3, { EggStep{ 3, 30, 0, true, 600.0f, 900.0f, false, 0.0f, "the hallowed ground", "Feed the hallowed ground: 30 of the dead slain on it at night", -1, false, "The ground near this altar is hallowed. Feed it thirty of the dead, slain where it glows.", "The ground is fed.", "", "The Hallowed Ground" }, EggStep{ 0, 5, 0, true, 600.0f, 1500.0f, false, 0.0f, "blade-shard", "Gather the five blade-shards at night - each guardian rises as you near", -1, false, "Five shards of the old blade lie scattered tonight. Their guardians wake when you come near.", "The blade is gathered.", "guardians", "The Blade-Shards" }, EggStep{ 1, 4, 0, true, 350.0f, 800.0f, false, 0.0f, "rune-stone", "Strike the four rune-stones with steel in the order they sing", -1, false, "Four rune-stones sing in turn. Strike them with steel, in the order they sing.", "The runes remember the blade.", "steel", "The Singing Runes" }, EggStep{ 6, 40, 0, true, 0.0f, 0.0f, false, 0.0f, "", "40 of the dead slain with your blade at night, a spell ready in your other hand", -1, false, "Swear the oath in steel. Forty of the dead by your blade, a spell ready in your other hand.", "The oath is sworn.", "bladespell", "The Oath in Steel" }, EggStep{ 5, 1, 0, true, 0.0f, 0.0f, false, 0.0f, "Thorgar the Skulltaker", "Defeat Thorgar the Skulltaker with the blade alone - magic won't touch him", 71, false, "Thorgar the Skulltaker holds the hilt. Magic will not touch him. Face him with the blade alone.", "The hilt is yours.", "thorgar", "Thorgar the Skulltaker" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" }, EggStep{ 2, 0, 0, false, 0.0f, 0.0f, false, 0.0f, "", "", -1, false, "", "", "", "" } }, 5, 0xCE4, 0xCE8, "oath", "A slayer swore an oath and broke his blade on Alduin's scales. Take up his oath, and the Dragon Slayer will be yours.", "The blade is whole. The Greybeards are calling. The Dragon Slayer waits at High Hrothgar." },
	} };
