	inline constexpr std::array<std::string_view, 10> kWhisperCity{ { "...where the mill wheel turns beside the river, over the hill from where the dragon first broke the sky.", "...beneath the hall built on a dragon's cage, where the golden tree grows.", "...where the great arch spans the sea, and the bards keep their songs.", "...in the oldest city of stone, where the snow never leaves the palace of kings.", "...in the city the deep elves carved, where the cliffs bleed silver.", "...where the canals run beneath a city of thieves and honey.", "...among the graves in the pines, where the dead outnumber the living.", "...in the marsh town, where the mist hides what walks.", "...on the cold northern shore, where the dreamers cannot sleep.", "...where the city fell into the sea, and the college stands alone." } };
