	inline constexpr std::array<WhisperSound, 67> kWhispers{ { WhisperSound{ "echo_asleep", Sound::wh_asleep, 8.88f }, WhisperSound{ "echo_city_dawnstar", Sound::wh_city_dawnstar, 7.32f }, WhisperSound{ "echo_city_falkreath", Sound::wh_city_falkreath, 6.96f }, WhisperSound{ "echo_city_markarth", Sound::wh_city_markarth, 7.47f }, WhisperSound{ "echo_city_morthal", Sound::wh_city_morthal, 6.72f }, WhisperSound{ "echo_city_riften", Sound::wh_city_riften, 6.69f }, WhisperSound{ "echo_city_riverwood", Sound::wh_city_riverwood, 9.65f }, WhisperSound{ "echo_city_solitude", Sound::wh_city_solitude, 8.05f }, WhisperSound{ "echo_city_whiterun", Sound::wh_city_whiterun, 8.21f }, WhisperSound{ "echo_city_windhelm", Sound::wh_city_windhelm, 8.69f }, WhisperSound{ "echo_city_winterhold", Sound::wh_city_winterhold, 7.35f }, WhisperSound{ "echo_eye_final", Sound::wh_eye_final, 11.73f }, WhisperSound{ "echo_eye_open", Sound::wh_eye_open, 17.81f }, WhisperSound{ "echo_eye_s1", Sound::wh_eye_s1, 15.36f }, WhisperSound{ "echo_eye_s1_done", Sound::wh_eye_s1_done, 3.36f }, WhisperSound{ "echo_eye_s2", Sound::wh_eye_s2, 8.73f }, WhisperSound{ "echo_eye_s2_done", Sound::wh_eye_s2_done, 3.02f }, WhisperSound{ "echo_eye_s3", Sound::wh_eye_s3, 16.64f }, WhisperSound{ "echo_eye_s3_done", Sound::wh_eye_s3_done, 3.29f }, WhisperSound{ "echo_eye_s4", Sound::wh_eye_s4, 10.90f }, WhisperSound{ "echo_eye_s4_done", Sound::wh_eye_s4_done, 3.13f }, WhisperSound{ "echo_eye_s5", Sound::wh_eye_s5, 12.12f }, WhisperSound{ "echo_eye_s5_done", Sound::wh_eye_s5_done, 4.02f }, WhisperSound{ "echo_next", Sound::wh_next, 3.71f }, WhisperSound{ "echo_oath_final", Sound::wh_oath_final, 11.59f }, WhisperSound{ "echo_oath_open", Sound::wh_oath_open, 13.33f }, WhisperSound{ "echo_oath_s1", Sound::wh_oath_s1, 10.57f }, WhisperSound{ "echo_oath_s1_done", Sound::wh_oath_s1_done, 2.98f }, WhisperSound{ "echo_oath_s2", Sound::wh_oath_s2, 10.10f }, WhisperSound{ "echo_oath_s2_done", Sound::wh_oath_s2_done, 3.45f }, WhisperSound{ "echo_oath_s3", Sound::wh_oath_s3, 10.11f }, WhisperSound{ "echo_oath_s3_done", Sound::wh_oath_s3_done, 3.46f }, WhisperSound{ "echo_oath_s4", Sound::wh_oath_s4, 11.05f }, WhisperSound{ "echo_oath_s4_done", Sound::wh_oath_s4_done, 3.29f }, WhisperSound{ "echo_oath_s5", Sound::wh_oath_s5, 12.60f }, WhisperSound{ "echo_oath_s5_done", Sound::wh_oath_s5_done, 3.05f }, WhisperSound{ "echo_pride_final", Sound::wh_pride_final, 11.85f }, WhisperSound{ "echo_pride_open", Sound::wh_pride_open, 15.24f }, WhisperSound{ "echo_pride_s1", Sound::wh_pride_s1, 13.04f }, WhisperSound{ "echo_pride_s1_done", Sound::wh_pride_s1_done, 4.24f }, WhisperSound{ "echo_pride_s2", Sound::wh_pride_s2, 13.66f }, WhisperSound{ "echo_pride_s2_done", Sound::wh_pride_s2_done, 4.22f }, WhisperSound{ "echo_pride_s3", Sound::wh_pride_s3, 11.37f }, WhisperSound{ "echo_pride_s3_done", Sound::wh_pride_s3_done, 3.47f }, WhisperSound{ "echo_pride_s4", Sound::wh_pride_s4, 11.22f }, WhisperSound{ "echo_pride_s4_done", Sound::wh_pride_s4_done, 2.94f }, WhisperSound{ "echo_pride_s5", Sound::wh_pride_s5, 9.73f }, WhisperSound{ "echo_pride_s5_done", Sound::wh_pride_s5_done, 3.66f }, WhisperSound{ "echo_stone_final", Sound::wh_stone_final, 9.87f }, WhisperSound{ "echo_stone_open", Sound::wh_stone_open, 13.93f }, WhisperSound{ "echo_stone_s1", Sound::wh_stone_s1, 13.74f }, WhisperSound{ "echo_stone_s1_done", Sound::wh_stone_s1_done, 6.07f }, WhisperSound{ "echo_stone_s2", Sound::wh_stone_s2, 9.19f }, WhisperSound{ "echo_stone_s2_done", Sound::wh_stone_s2_done, 3.07f }, WhisperSound{ "echo_stone_s3", Sound::wh_stone_s3, 10.27f }, WhisperSound{ "echo_stone_s3_done", Sound::wh_stone_s3_done, 3.04f }, WhisperSound{ "echo_stone_s4", Sound::wh_stone_s4, 11.09f }, WhisperSound{ "echo_stone_s4_done", Sound::wh_stone_s4_done, 4.39f }, WhisperSound{ "echo_stone_s5", Sound::wh_stone_s5, 9.61f }, WhisperSound{ "echo_stone_s5_done", Sound::wh_stone_s5_done, 3.34f }, WhisperSound{ "echo_voice_2", Sound::wh_voice_2, 17.13f }, WhisperSound{ "echo_voice_4", Sound::wh_voice_4, 21.67f }, WhisperSound{ "echo_voice_6", Sound::wh_voice_6, 27.44f }, WhisperSound{ "echo_pride_sign", Sound::wh_pride_sign, 10.05f }, WhisperSound{ "echo_eye_sign", Sound::wh_eye_sign, 7.51f }, WhisperSound{ "echo_stone_sign", Sound::wh_stone_sign, 10.17f }, WhisperSound{ "echo_oath_sign", Sound::wh_oath_sign, 8.84f } } };
	struct TalkLine { std::string_view key, text; float secs; };
	inline constexpr std::array<std::uint32_t, 6> kTalkHeard{ { 0xDE7, 0xDEA, 0xDED, 0xDF0, 0xDF3, 0xDF6 } };
	struct TalkPrompt { std::string_view id, gate, ask; std::uint8_t topic; std::uint16_t first, count; };
	inline constexpr std::array<std::string_view, 5> kTalkTopics{ { "Greeting and farewell", "The story so far", "This city", "Your class and wonder", "Who the voice is" } };
	inline constexpr std::array<TalkLine, 180> kTalkLines{ { TalkLine{ "av_bye_1", "Go. I will be in the stone.", 4.43f }, TalkLine{ "av_bye_2", "Walk carefully. The dead remember the living.", 6.58f }, TalkLine{ "av_bye_3", "Until the next stone.", 4.63f }, TalkLine{ "av_bye_4", "The night will come again. Be ready for it.", 6.65f }, TalkLine{ "av_nothing_new_1", "I have told you all I know of that. For now.", 6.28f }, TalkLine{ "av_nothing_new_2", "Nothing more... not yet. Free another stone, and I may remember more.", 10.32f }, TalkLine{ "av_s_what_1", "Helgen burned. The World-Eater flew north over the smoke... and as he flew, he shouted into the earth.", 12.30f }, TalkLine{ "av_s_what_2", "Three words. SLEN... TIID... VO. Flesh. Time. Undo. The shout he raises his dragons with.", 16.77f }, TalkLine{ "av_s_what_3", "But this time it fell on every grave in Skyrim. And every grave heard it.", 10.70f }, TalkLine{ "av_s_dead_1", "His shout hangs like a mist over every road the dead walk. Shor's hall, Arkay's mercy, whatever waits for them... none of them can pass it.", 16.44f }, TalkLine{ "av_s_dead_2", "They try, every night. The mist turns them back... and his voice throws them down to Skyrim again, as red light out of the sky.", 14.63f }, TalkLine{ "av_s_beams_1", "The dead, falling. Turned back from Sovngarde, and thrown down wherever his voice is strongest.", 10.93f }, TalkLine{ "av_s_beams_2", "The red lightning is worse. That is how the strong ones come... the ones his voice holds tightest.", 13.11f }, TalkLine{ "av_s_altars_1", "Echo Altars. The old Tongues raised one in every hold, long before your Empire, to answer a dragon's voice with their own.", 15.59f }, TalkLine{ "av_s_altars_2", "When the World-Eater shouted, they went dark. Wake one, and its city's dead will sleep again.", 11.09f }, TalkLine{ "av_s_how_1", "...four trials... at night... the dead... the stone will show you...", 9.80f }, TalkLine{ "av_s_how_2", "...one city at a time... and then I will be clearer...", 8.20f }, TalkLine{ "av_s_me_1", "You have a dragon's soul in a mortal's body. When you kill one of the dead, the stone hears it the way it hears a shout.", 13.57f }, TalkLine{ "av_s_me_2", "The Tongues would have given anything to be what you are. Do not waste it.", 9.36f }, TalkLine{ "av_s_essence_1", "What is left of his shout in the dead. When they fall, it comes out of them... and it comes to you.", 11.18f }, TalkLine{ "av_s_essence_2", "The stone can make it into steel, and spells, and brews. Spend it. It does no good in your pocket.", 11.74f }, TalkLine{ "av_s_fall_1", "The dead will drag you down. If anyone stands with you, they can lift you again. If no one does... the night ends without you.", 14.88f }, TalkLine{ "av_s_fall_2", "Do not let it. I have lost enough people to the dark.", 7.22f }, TalkLine{ "av_s_tablet_1", "An old thing, and a strange one. The Tongues left weapons with it that they did not want to keep.", 10.25f }, TalkLine{ "av_s_tablet_2", "Feed it the essence, and it will give you one. It does not tell you which. Neither will I.", 12.58f }, TalkLine{ "av_s_shouts_1", "Every freed city remembers a little of the Voice. They teach it to the one who freed them.", 9.74f }, TalkLine{ "av_s_shouts_2", "Use them. A shout is a weapon the dead cannot answer.", 7.46f }, TalkLine{ "av_s_two_1", "Two stones awake, and their voices carry to each other. That is how you hear me now.", 10.31f }, TalkLine{ "av_s_two_2", "Every stone you wake makes the mist thinner. Not gone... but thinner.", 9.73f }, TalkLine{ "av_s_cities_1", "Each altar answers for its own hold. The dead of Whiterun do not care that Riverwood sleeps.", 11.58f }, TalkLine{ "av_s_cities_2", "And each city has its keeper. A priest who swore an oath to the World-Eater... and remembers it.", 12.45f }, TalkLine{ "av_s_priests_1", "Men who served the dragons when the dragons ruled. They wore masks of the dragons' faces, and took the dragons' power.", 12.17f }, TalkLine{ "av_s_priests_2", "When the shout came, every one of them woke with his oath still in his mouth. They keep the altars dark for their master.", 11.74f }, TalkLine{ "av_s_priests_3", "Break a city's seals, and its priest must come out to face you.", 6.83f }, TalkLine{ "av_s_four_1", "Four stones. Five. The mist trembles when the sixth wakes... I can feel it already.", 12.54f }, TalkLine{ "av_s_four_2", "At six... I will be able to tell you who I am. And something old will begin to stir.", 13.38f }, TalkLine{ "av_s_wonders_1", "The wonders. Four weapons, one for each path, hidden when the Tongues still walked. They sleep no longer.", 13.86f }, TalkLine{ "av_s_wonders_2", "Each waits for the one who walks its path. But none of them will simply be found. Each must be earned.", 13.84f }, TalkLine{ "av_s_wonders_3", "When yours is won, the Greybeards will call you to the mountain. The wonder waits beneath their hall.", 11.15f }, TalkLine{ "av_s_greybeards_1", "High Hrothgar sits on the Throat of the World. Where the Tongues cast the World-Eater out of time.", 10.73f }, TalkLine{ "av_s_greybeards_2", "Beneath it is a room the Greybeards guard and do not speak of. The wonders are kept there, until they are won.", 14.10f }, TalkLine{ "av_s_echo_what_1", "When we cast him out of time, his voice did not all go with him. Part of it stayed behind, caught on the summit where we broke him.", 15.01f }, TalkLine{ "av_s_echo_what_2", "It has circled there since, waiting. Now that he is back in the world, it answers him... and it is louder than ever.", 14.15f }, TalkLine{ "av_s_echo_what_3", "He flies where he likes. The echo cannot leave the mountain. That is why you can reach it... and why breaking it breaks his hold on the dead.", 15.48f }, TalkLine{ "av_s_ten_1", "Every stone sings again. Listen... all of Skyrim answering at once. I have not heard that in a very long time.", 16.17f }, TalkLine{ "av_s_ten_2", "But the World-Eater's voice is not gone. It lingers in the wild places... and in the echo he left on the summit.", 13.39f }, TalkLine{ "av_s_ten_3", "The cities are safe. The rest of Skyrim is not. Not yet.", 8.53f }, TalkLine{ "av_s_dragons_1", "Now the words wake. Each of the three words of his shout was carried by a dragon. They are flying again.", 12.95f }, TalkLine{ "av_s_dragons_2", "SLEN in the Reach. TIID under Labyrinthian. VO on the peak of Mount Anthor. Silence all three.", 13.48f }, TalkLine{ "av_s_dragons_3", "Each will come at night, with a siege of the dead before it. And each one gives back what it stole.", 10.76f }, TalkLine{ "av_s_slen_1", "Slenvahrin. The Flesh-Wyrm. It circles the cult's old shrine in the Reach, and the barrow-dead around it grow new flesh.", 15.46f }, TalkLine{ "av_s_slen_2", "Kill it, and the strength the World-Eater poured into the dead will run in you instead.", 8.07f }, TalkLine{ "av_s_tiid_1", "Tiidrah. The Time-Wyrm. It sleeps under Labyrinthian, where the cult laid its dead by the thousand.", 11.74f }, TalkLine{ "av_s_tiid_2", "It gives the dead back the years the grave took. Take them from it... and the time is yours.", 11.88f }, TalkLine{ "av_s_vo_1", "Vonahlok. The Undoing. It keeps the last word, on the frozen peak of Mount Anthor.", 11.30f }, TalkLine{ "av_s_vo_2", "Where it flies, death itself comes undone. It is the oldest of the three... and the angriest.", 11.49f }, TalkLine{ "av_s_slen_done_1", "I felt it fall. SLEN is silent... the dead in the Reach are only bones again. You are stronger for it.", 15.28f }, TalkLine{ "av_s_tiid_done_1", "TIID is silent. The time the dead stole is yours now. Spend it better than they did.", 11.94f }, TalkLine{ "av_s_vo_done_1", "The Undoing has undone its last. I never thought I would hear VO go quiet.", 10.44f }, TalkLine{ "av_s_echo_1", "Only their maker. On the summit of the Throat of the World, where we cast him out of time, his echo still circles.", 11.81f }, TalkLine{ "av_s_echo_2", "It is not the World-Eater himself. Only the shape his voice left in the sky. It is enough to kill you.", 12.40f }, TalkLine{ "av_s_echo_3", "Break it... and the curse breaks with it. Every grave in Skyrim will be quiet.", 9.63f }, TalkLine{ "av_s_echo_how_1", "Bring everything you have earned. The wonder. The words you took from the three. And anyone who will stand with you.", 14.65f }, TalkLine{ "av_s_echo_how_2", "It will call the dead of all Skyrim to the summit. Do not let them pull you away from it.", 9.01f }, TalkLine{ "av_s_after_1", "Here, it is. The echo is broken, and Skyrim's dead are sleeping again. The nights are only nights.", 12.04f }, TalkLine{ "av_s_after_2", "But the World-Eater himself still lives. Without his echo, he has nowhere left to hide... but Sovngarde.", 10.35f }, TalkLine{ "av_s_after_3", "He will go there to feed on the souls of the dead. That is where the last fight waits for you.", 7.51f }, TalkLine{ "av_s_hall_1", "A room beneath High Hrothgar that opened when the echo broke. The Tongues built it for whoever ended this.", 12.01f }, TalkLine{ "av_s_hall_2", "It is yours now. Go and see it.", 5.65f }, TalkLine{ "av_c_riverwood_free_1", "The mill wheel turns, and no red light falls over the barrow. Listen... it is a quiet valley again.", 12.81f }, TalkLine{ "av_c_riverwood_free_2", "This was the first stone you woke. I will remember that.", 7.00f }, TalkLine{ "av_c_riverwood_old_1", "When we raised this stone, there was no town here. Only the river, and a dragon's nest on the mountain above it.", 11.90f }, TalkLine{ "av_c_whiterun_free_1", "The Gildergreen is quiet. The plains are only grass again.", 7.68f }, TalkLine{ "av_c_whiterun_free_2", "Nahkriin's gate has one less keeper. The road to Sovngarde is a little clearer for it.", 10.44f }, TalkLine{ "av_c_whiterun_old_1", "The dragon in Dragonsreach was not the first caged on that hill. The first was there in our time. We heard it screaming for a year.", 15.24f }, TalkLine{ "av_c_solitude_free_1", "The arch over the sea is quiet. The bards can sing of the dead again, instead of to them.", 11.73f }, TalkLine{ "av_c_solitude_free_2", "Solitude will tell this story for a hundred years. They will get it wrong. Let them.", 11.12f }, TalkLine{ "av_c_solitude_old_1", "There were Tongues who lived on these cliffs, and taught their students to shout across the water. The sea still remembers the sound.", 12.82f }, TalkLine{ "av_c_windhelm_free_1", "The candle still burns, and nothing comes to it but the living.", 7.80f }, TalkLine{ "av_c_windhelm_free_2", "Windhelm has buried enough of its own. It can rest now.", 7.38f }, TalkLine{ "av_c_windhelm_old_1", "Ysgramor's people built over the stone without knowing it was here. It has listened to every king of Windhelm since.", 13.53f }, TalkLine{ "av_c_markarth_free_1", "The stone city is still. Even the Reach's oldest dead have gone back to sleep.", 9.17f }, TalkLine{ "av_c_markarth_free_2", "Otar is gone. I will not mourn him. Neither did his cult.", 8.55f }, TalkLine{ "av_c_markarth_old_1", "The deep elves had a stone of their own, under the cliff. Ours answered it once. Nothing answers from down there now.", 13.71f }, TalkLine{ "av_c_riften_free_1", "The canal is only water again. The thieves can go back to stealing from the living.", 8.98f }, TalkLine{ "av_c_riften_free_2", "Rahgot's followers died for him twice. Let them stay dead this time.", 9.67f }, TalkLine{ "av_c_riften_old_1", "The lake here was a holy place to Mara before there was a city. We raised the stone where her pilgrims rested.", 11.25f }, TalkLine{ "av_c_falkreath_free_1", "The rows are quiet. Falkreath can bury its dead and leave them buried.", 9.46f }, TalkLine{ "av_c_falkreath_free_2", "Krosis grieved for a thousand years. I hope he has stopped.", 7.76f }, TalkLine{ "av_c_falkreath_old_1", "Even in our time, people came here to bury their dead. Some places are made for grief.", 10.42f }, TalkLine{ "av_c_morthal_free_1", "The fog is only fog again. Morthal can sleep with its doors unbarred.", 9.50f }, TalkLine{ "av_c_morthal_free_2", "Hevnoraak's servants were right to seal him. You finished what they started.", 8.50f }, TalkLine{ "av_c_morthal_old_1", "The marsh swallowed the first stone we raised here. This is the second. We were careful where we put it.", 12.26f }, TalkLine{ "av_c_dawnstar_free_1", "The harbour is frozen and still. Tonight, Dawnstar will sleep without dreaming.", 10.12f }, TalkLine{ "av_c_dawnstar_free_2", "The nightmares are over here. For once, the dreamers will wake rested.", 9.08f }, TalkLine{ "av_c_dawnstar_old_1", "There was a shrine in the hills here to a god of dreams. We built the stone well away from it. We were right to.", 12.09f }, TalkLine{ "av_c_winterhold_free_1", "The storm has passed. The bridge to the College is only a bridge again.", 8.38f }, TalkLine{ "av_c_winterhold_free_2", "Morokei is gone, and the College will claim the credit. Let it.", 7.80f }, TalkLine{ "av_c_winterhold_old_1", "This stone once stood in a great city. The sea took the city. The stone held on. So did the College.", 13.13f }, TalkLine{ "av_k_paths_1", "The stone offers four ways to fight the dead. The Tongues walked all of them, once.", 10.87f }, TalkLine{ "av_k_paths_2", "The Summoner, who calls the dead's own kind to fight them. The Destruction mage, who burns them where they stand.", 12.94f }, TalkLine{ "av_k_paths_3", "The Alchemist, who bottles every element and pours it out. The Spellsword, steel in one hand and a spell in the other.", 14.21f }, TalkLine{ "av_k_paths_4", "Choose at the stone. Choosing again later costs dearly, so choose well.", 9.65f }, TalkLine{ "av_k_change_1", "The stone will let you. It will cost you fifty thousand of the essence the dead leave behind.", 10.72f }, TalkLine{ "av_k_change_2", "Your kit stays your own. But your path's powers stay with the path.", 9.56f }, TalkLine{ "av_k_sum_seen_1", "You call things to fight for you, and they come. The Tongues had a word for people like you. It was not a kind word.", 14.94f }, TalkLine{ "av_k_sum_seen_2", "But it was a useful one. The dead fear what does not fear them.", 8.68f }, TalkLine{ "av_k_sum_craft_1", "Let your servants hold the line. You are the one who must not fall. Without you, they go back where they came from.", 15.28f }, TalkLine{ "av_k_sum_craft_2", "The more you call, the thinner you are spread. Be wise about it.", 8.13f }, TalkLine{ "av_k_sum_sleep_1", "There is. The Soulcaller's Staff. But it sleeps, and it will not wake until six stones are free.", 11.04f }, TalkLine{ "av_k_sum_quest_1", "Listen... the ghost-cats that guarded the Tongues still prowl. Their souls are scattered. Gather them.", 11.79f }, TalkLine{ "av_k_sum_quest_2", "Follow them quietly at night, near a freed stone. They fear the hunter. They will come to a patient one.", 12.43f }, TalkLine{ "av_k_sum_won_1", "The Soulcaller's Staff. Every soul it takes is one the dead will never get back.", 9.63f }, TalkLine{ "av_k_sum_won_2", "At twenty souls the pride answers. They remember who freed them.", 8.47f }, TalkLine{ "av_k_sum_old_1", "One of us could call the wolves down from the mountain with a word. They followed her to the summit. None of them came back.", 13.05f }, TalkLine{ "av_k_des_seen_1", "Fire. Frost. Storm. You do not ask the dead to sleep. You make them.", 12.18f }, TalkLine{ "av_k_des_seen_2", "The Tongues had mages like you. The dragons learned to fear them... for a while.", 9.83f }, TalkLine{ "av_k_des_craft_1", "Your power is in your magicka, and your magicka runs out. Never let the dead catch you empty.", 10.49f }, TalkLine{ "av_k_des_craft_2", "Each element has its use. Fire for the crowd. Frost to slow them. Storm for whatever is still standing.", 13.49f }, TalkLine{ "av_k_des_sleep_1", "There is. The Wyrmspine Javelin. But it sleeps, and it will not wake until six stones are free.", 13.23f }, TalkLine{ "av_k_des_quest_1", "A god's eye fell to Nirn, and the curse buried its light. The Eye of Magnus... its pieces are falling again.", 14.05f }, TalkLine{ "av_k_des_quest_2", "When a star crosses the sky above you at night, strike it down. That is where the path begins.", 10.94f }, TalkLine{ "av_k_des_won_1", "The Wyrmspine Javelin. Carved from a dragon's spine, and it remembers the sky.", 11.26f }, TalkLine{ "av_k_des_won_2", "Throw it hard. It wants to fly again.", 5.60f }, TalkLine{ "av_k_des_old_1", "Our fire-callers burned the dragons' priests out of their towers. The dragons answered in kind. Fire was cheap in those days.", 14.05f }, TalkLine{ "av_k_alc_seen_1", "You bottle what the rest of us fear. Fire in glass, frost in glass... even, one day, the curse itself.", 16.38f }, TalkLine{ "av_k_alc_seen_2", "The Tongues never trusted alchemists. They trusted their potions well enough.", 7.65f }, TalkLine{ "av_k_alc_craft_1", "Your flasks are your strength. Know which element the dead fear, and give them that one.", 11.50f }, TalkLine{ "av_k_alc_craft_2", "Never stand still to brew. The dead do not wait for anything to cool.", 8.68f }, TalkLine{ "av_k_alc_sleep_1", "There is. The Mutagen Staff. But it sleeps, and it will not wake until six stones are free.", 13.21f }, TalkLine{ "av_k_alc_quest_1", "Every element can be bottled. Brew the Elixir of Aetherius... and the Mutagen Staff will answer you.", 10.96f }, TalkLine{ "av_k_alc_quest_2", "One of the dead burns brighter than the rest. Break it with glass... and catch what falls.", 10.79f }, TalkLine{ "av_k_alc_won_1", "The Mutagen Staff. Six vials of the world's elements, poured through one orb.", 9.81f }, TalkLine{ "av_k_alc_won_2", "The Elixir of Aetherius was only ever a story. You made it true.", 8.65f }, TalkLine{ "av_k_alc_old_1", "We had a healer who brewed in a skull, because it was the only bowl she had. She kept more of us alive than the Voice did.", 14.56f }, TalkLine{ "av_k_ssw_seen_1", "Steel in one hand, a spell in the other. You fight the way the first Tongues fought, before they had the Voice.", 13.00f }, TalkLine{ "av_k_ssw_seen_2", "You get closer to the dead than anyone should. They feel it.", 7.27f }, TalkLine{ "av_k_ssw_craft_1", "Your blade carries your spell. Choose the spell before you choose the fight.", 8.78f }, TalkLine{ "av_k_ssw_craft_2", "Get close, and stay close. A Spellsword at the edge of a fight is only half of one.", 11.28f }, TalkLine{ "av_k_ssw_sleep_1", "There is. The Dragon Slayer. But it sleeps, and it will not wake until six stones are free.", 14.26f }, TalkLine{ "av_k_ssw_quest_1", "A slayer once swore an oath and broke his blade on the World-Eater's scales. The pieces are scattered.", 10.71f }, TalkLine{ "av_k_ssw_quest_2", "Take up his oath. Where the World-Eater first returned, a broken blade waits for a hand. Begin there.", 13.40f }, TalkLine{ "av_k_ssw_won_1", "The Dragon Slayer. Every blow carries the spell in your other hand.", 8.18f }, TalkLine{ "av_k_ssw_won_2", "The slayer's oath is kept. He would have been glad of you.", 7.66f }, TalkLine{ "av_k_ssw_old_1", "Before the Voice, we had steel and a little magic, and we fought dragons with that. Most of us died. The ones who lived taught the rest.", 18.04f }, TalkLine{ "av_k_party_1", "Each of you walks a path of your own. Together, you are what the Tongues were. Stay together.", 12.70f }, TalkLine{ "av_k_party_2", "If one of you falls, the rest of you lift them. The dead do not take prisoners.", 9.65f }, TalkLine{ "av_v_who0_1", "...someone who has waited... too long... wake another stone...", 9.70f }, TalkLine{ "av_v_who2_1", "Someone who was here when these stones were raised. That is all I can give you... for now.", 11.60f }, TalkLine{ "av_v_who2_2", "My name is in the mist with everything else. Wake more stones, and it will come back to me.", 10.04f }, TalkLine{ "av_v_where2_1", "Far. Behind the mist he left across the road to Sovngarde. I speak through the stones because I cannot speak any other way.", 15.39f }, TalkLine{ "av_v_old_1", "Older than your Empire. Older than the first Nord kings. They were raised while dragons still ruled the sky.", 13.66f }, TalkLine{ "av_v_old_2", "We raised them in secret, in the dark, where the dragons' priests would not see.", 9.27f }, TalkLine{ "av_v_three_1", "The three of us. The first who learned the Voice... and turned it on our masters.", 9.54f }, TalkLine{ "av_v_three_2", "One fell at the summit, before the end. One I have not seen since. And I... I am still here.", 15.12f }, TalkLine{ "av_v_fell_1", "A warrior with a golden hilt. She was the bravest of us. She went at him first, and he took her first.", 12.71f }, TalkLine{ "av_v_fell_2", "I watched her fall. I did not stop. That is what she would have wanted.", 9.72f }, TalkLine{ "av_v_lost_1", "A warrior with one eye, who saw more than most with two. After the summit... I lost him in the mist.", 12.26f }, TalkLine{ "av_v_lost_2", "Perhaps he is in Sovngarde, waiting for the road to open. I hope so.", 9.36f }, TalkLine{ "av_v_name_1", "Six stones are free... and I remember. I am Felldir. Felldir the Old.", 12.18f }, TalkLine{ "av_v_name_2", "It has been a very long time since anyone asked me that.", 6.74f }, TalkLine{ "av_v_scroll_1", "I read the Elder Scroll. The others held him in the sky, and I read it... and the World-Eater was cast out of time.", 13.50f }, TalkLine{ "av_v_scroll_2", "We thought it was the end. We were young. We did not know that time has a way of giving things back.", 10.88f }, TalkLine{ "av_v_wait_1", "I lived a long life after the summit, and died old, and took the road to Sovngarde. When he shouted at Helgen, the mist fell over it... with me still on it.", 19.86f }, TalkLine{ "av_v_wait_2", "I cannot go forward, and I will not go back. So I wait... and I speak through the stones we raised.", 12.89f }, TalkLine{ "av_v_alone_1", "The dead pass me in the mist. They cannot see the way. Neither can I. We are all lost together.", 12.55f }, TalkLine{ "av_v_alone_2", "Then you came. The first living voice I have heard in a very long time.", 9.49f }, TalkLine{ "av_v_alduin_1", "Proud. Patient. He did not hate us. You do not hate the grass you walk on.", 11.24f }, TalkLine{ "av_v_alduin_2", "That is what frightened me most. Not his anger... his certainty.", 9.14f }, TalkLine{ "av_v_dragonborn_1", "We hoped. The Scroll told us he would come back. It did not tell us who would be waiting when he did.", 11.62f }, TalkLine{ "av_v_dragonborn_2", "I am glad it was you.", 4.36f }, TalkLine{ "av_v_greybeards_1", "They came after us. They took the Voice and made it quiet, and climbed the mountain to keep it safe.", 10.75f }, TalkLine{ "av_v_greybeards_2", "We used it to fight. They use it to listen. Perhaps they are wiser than we were.", 10.78f }, TalkLine{ "av_v_dragons_1", "I did. For a long time. Then I was dead for longer than I was ever alive, and hate is hard to carry that far.", 13.94f }, TalkLine{ "av_v_dragons_2", "Now I only want them to stop. That is not the same thing.", 7.78f }, TalkLine{ "av_v_deadwant_1", "To go home. Nothing more. They are not cruel... they are lost, and the World-Eater's voice is all they can hear.", 14.49f }, TalkLine{ "av_v_deadwant_2", "When you put them down, you are not killing them. You are showing them the way.", 9.82f }, TalkLine{ "av_v_after_1", "I go back into the mist, to wait with the others. A golden hilt... and one eye. They are there. I can feel them.", 12.83f }, TalkLine{ "av_v_after_2", "When you come to Sovngarde, we will be waiting. Three old voices, ready to shout beside you one more time.", 10.22f }, TalkLine{ "av_v_after_3", "Thank you, Dragonborn. Until Sovngarde.", 5.13f } } };
